WITH kept_keys AS (SELECT id, promo_code FROM promotions INTERSECT ALL SELECT id, promo_code FROM promotions WHERE MONTH(ends_on) IN (4, 8, 10)), reconciled AS (SELECT s.* FROM promotions s JOIN kept_keys k ON s.id = k.id AND s.promo_code = k.promo_code) SELECT channel, DATE_TRUNC('WEEK', ends_on) AS week_start, COUNT_IF(promo_code = 'BUNDLE') AS bundle_events, APPROX_PERCENTILE(discount_pct, 0.95) AS discount_pct_p95, COUNT(CASE WHEN promo_code = 'VIP' THEN 1 END) AS vip_count, APPROX_PERCENTILE(discount_pct, 0.9) AS discount_pct_p90, COUNT_IF(channel = 'partner') AS partner_events, APPROX_PERCENTILE(discount_pct, 0.95) AS discount_pct_p95_2, GROUPING_ID() AS grouping_level FROM reconciled GROUP BY ROLLUP (channel, DATE_TRUNC('WEEK', ends_on)) ORDER BY vip_count DESC;
